/**
 * This test case verifies CBRD-27245: Improve lexer input handling for UTF-8 statements
 *
 * 1-3  - no padding (control): parses correctly nowhere near a boundary
 * 4-6  - padding exactly on the first refill boundary (offset 8192)
 * 7    - semicolon inside a literal followed by a second statement same line
 * 8-9  - the UTF-8 character from cbrd_27245_utf8fix.sql, in a literal and as
 *        an alias, straddling the first refill boundary (offset 8192).
 *        9 fails without the fix, same as cbrd_27245_utf8fix.sql
 */

SET SYSTEM PARAMETERS 'no_backslash_escapes=no';

evaluate 'Case 1: escaped quote pair (\') control';
SELECT 'a\'b', 'END_QUOTE' FROM dual;

evaluate 'Case 2: escaped backslash pair (\\) control';
SELECT 'a\\', 'END_BACKSLASH' FROM dual;

evaluate 'Case 3: backslash-n escape (\\n) control';
SELECT '\n', 'END_NEWLINE' FROM dual;

evaluate 'Case 4: escaped quote pair (\') exactly on the first refill boundary (8192 byte), splitting the pair';
SELECT '\'b' AS case4, 'END_QUOTE' FROM dual;

evaluate 'Case 5: escaped backslash pair (\\) exactly on the first refill boundary (8192 byte), splitting the pair, closing quote right after';
SELECT '\\' AS case5, 'END_BACKSLASH' FROM dual;

evaluate 'Case 6: backslash-n escape (\\n) exactly on the first refill boundary (8192 byte), splitting the pair';
SELECT '\n' AS case6, 'END_NEWLINE' FROM dual;

evaluate 'Case 7: semicolon inside a string literal immediately followed by a second statement on the same line';
SELECT 'boundary;semicolon' FROM dual; SELECT 2 FROM dual;

evaluate 'Case 8: a multi-byte UTF-8 character (U+21861) inside a string literal, straddling the first refill boundary (byte offset 8192)';
SELECT '𡡡' AS case8, 'END_UTF8' FROM dual;

evaluate 'Case 9: the same character used as an alias (outside any literal), straddling the first refill boundary (byte offset 8192)';
SELECT '' AS case9, 1 AS t𡡡 FROM dual;
SET SYSTEM PARAMETERS 'no_backslash_escapes=yes';
